//! track_matte: reviewed seed outline(s) on a clip -> dense, temporally stable alpha matte over a frame range, attached as a `matte` mask layer.
use super::kit::*;
use crate::matte::{self, Opts, Store};
fn pts_of(v: &Value, w: f64, h: f64) -> Result<Vec<[f64; 2]>, String> { let a = v.as_array().ok_or("seed points must be an array")?; let mut o = vec![]; for p in a { let (x, y) = if let Some(q) = p.as_array() { (q.get(0).and_then(|v| v.as_f64()), q.get(1).and_then(|v| v.as_f64())) } else { (p.get("x").and_then(|v| v.as_f64()), p.get("y").and_then(|v| v.as_f64())) }; let (x, y) = (x.ok_or("bad point")?, y.ok_or("bad point")?); o.push([x, y]); }
    // normalised (all within 0..1.5) or pixels
    let norm = o.iter().all(|p| p[0].abs() <= 1.5 && p[1].abs() <= 1.5); if norm { for p in o.iter_mut() { p[0] *= w; p[1] *= h; } } Ok(o) }
pub fn commands() -> Vec<Command> { vec![
    Command { name: "track_matte", description: "Video matte tracker: propagate reviewed seed outline(s) through a clip into a dense, temporally stable alpha matte (partial alpha on blurred edges kept, no thresholding). Seeds: [{time (clip-local s), points [[x,y],..] in canvas pixels (or 0..1 normalised)}] drawn on the subject at those times; more seeds mid-clip are tracked both ways and blended, which fixes drift and crossings. Optical flow warps the alpha frame to frame, colour models anchored to the seed re-decide a band around the edge, a guided filter snaps it to image edges, and a flow-compensated forward/backward pass removes flicker. start/end (clip-local s) default to the seeds' span extended to the whole clip. Result: a `matte` mask layer (mask_id) on the clip, per-frame confidence, warnings, and measured flicker/jitter before vs after stabilisation. Tracks the clip as rendered (effects and transforms included; keep transforms at identity while tracking).", mutates: true,
        schema: obj(vec![("clip_id", s("media clip")), ("seeds", json!({"type":"array","items":{"type":"object","properties":{"time":{"type":"number"},"points":{"type":"array"}},"required":["time","points"]}})), ("start", n("clip-local s, default 0")), ("end", n("clip-local s, default clip end")), ("band", n("edge search band px, default 14")), ("temporal", n("0..0.95 stabilisation strength, default 0.6")), ("colour", n("colour evidence weight, default 0.9")), ("dir", s("output folder, default /tmp/kimo_matte_<id>")), ("add_mask", json!({"type":"boolean","description":"attach as a matte mask layer (default true)"})), ("mode", s("mask combine mode, default add"))], &["clip_id", "seeds"]),
        run: |ss, a| {
            let cid = str_arg(a, "clip_id")?.to_string(); let fps = ss.project.fps; let (w, h) = (ss.project.width as usize, ss.project.height as usize);
            let (cstart, cdur) = { let c = ss.project.find_clip(&cid).ok_or("no such clip")?; (c.start, c.duration) }; let nclip = ((cdur * fps).round() as usize).max(1);
            let sa = a.get("seeds").and_then(|v| v.as_array()).ok_or("seeds required")?; if sa.is_empty() { return Err("give at least one seed".into()); }
            let mut seeds: Vec<(usize, Vec<[f64; 2]>)> = vec![]; for sd in sa { let t = sd.get("time").and_then(|v| v.as_f64()).ok_or("seed time")?; let fi = (t * fps).round().max(0.0) as usize; let pts = pts_of(sd.get("points").ok_or("seed points")?, w as f64, h as f64)?; if pts.len() < 3 { return Err("a seed outline needs at least 3 points".into()); } seeds.push((fi, pts)); }
            let f0 = (opt_num(a, "start", 0.0) * fps).round().max(0.0) as usize; let f1 = ((opt_num(a, "end", cdur) * fps).round() as usize).min(nclip - 1).max(f0 + 1);
            if seeds.iter().any(|s| s.0 < f0 || s.0 > f1) { return Err("every seed time must lie inside start..end".into()); } if f1 + 1 - f0 > 240 { return Err("range too long for one call (max 240 frames); track it in pieces".into()); }
            let t0 = std::time::Instant::now(); let mut frames: Vec<Vec<u8>> = vec![];
            for i in f0..=f1 { let t = cstart + i as f64 / fps; crate::render::prepare_at(&ss.project, &mut ss.cache, Some(t))?; let f = crate::render::render_clip_alone(&ss.project, &cid, t, &ss.cache).ok_or("could not render the clip")?; let mut rgb = vec![0u8; w * h * 3]; for k in 0..w * h { for j in 0..3 { rgb[k * 3 + j] = (f.d[k * 4 + j].clamp(0.0, 1.0) * 255.0 + 0.5) as u8; } } frames.push(rgb); }
            let o = Opts { band: opt_num(a, "band", 14.0) as f32, temporal: opt_num(a, "temporal", 0.6) as f32, colour: opt_num(a, "colour", 0.9) as f32, ..Default::default() };
            let rel: Vec<(usize, Vec<[f64; 2]>)> = seeds.into_iter().map(|(f, p)| (f - f0, p)).collect(); let out = matte::track(&frames, w, h, &rel, &o)?;
            let mut d = Vec::with_capacity(out.alpha.len() * w * h); for fr in &out.alpha { for &v in fr.iter() { d.push((v.clamp(0.0, 1.0) * 255.0 + 0.5) as u8); } }
            let dir = a.get("dir").and_then(|v| v.as_str()).map(|x| x.to_string()).unwrap_or_else(|| format!("/tmp/kimo_matte_{}", cid)); matte::save(&dir, &Store { w, h, n: out.alpha.len(), d })?;
            let mut res = json!({"dir": dir, "frames": out.alpha.len(), "first_frame_s": f0 as f64 / fps, "seconds": t0.elapsed().as_secs_f64(), "flicker": {"before_stabilise": out.raw_flicker, "after": out.flicker}, "area_jitter": {"before_stabilise": out.raw_jitter, "after": out.jitter}, "confidence": out.conf.iter().map(|c| (c * 100.0).round() / 100.0).collect::<Vec<_>>(), "warnings": out.warnings});
            if a.get("add_mask").and_then(|v| v.as_bool()).unwrap_or(true) { let id = ss.project.gen_id("mask"); let mut l = crate::masks::new_layer(id.clone(), "matte"); l.strings.insert("dir".into(), dir.clone()); l.props.insert("start".into(), crate::keyframe::Prop::new(f0 as f64 / fps)); if let Some(m) = a.get("mode").and_then(|v| v.as_str()) { l.mode = m.into(); }
                let c = ss.project.find_clip_mut(&cid).ok_or("no such clip")?; let m = c.mask.get_or_insert_with(|| crate::model::Mask { shape: "stack".into(), props: Default::default(), invert: false, layers: vec![], matte: None }); m.layers.push(l); res["mask_id"] = json!(id); }
            Ok(res) } },
] }
